CREATE TABLE orchestrations(orchestration_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id)ON DELETE RESTRICT,created_by_provider TEXT NOT NULL,created_by_subject TEXT NOT NULL,created_at INTEGER NOT NULL CHECK(created_at>=0),FOREIGN KEY(created_by_provider,created_by_subject)REFERENCES identities(provider,subject)ON DELETE RESTRICT)STRICT;CREATE TABLE orchestration_graph_revisions(orchestration_id TEXT NOT NULL REFERENCES orchestrations(orchestration_id)ON DELETE CASCADE,revision INTEGER NOT NULL CHECK(revision>0),graph_digest TEXT NOT NULL CHECK(length(graph_digest)=64 AND graph_digest NOT GLOB'*[^0-9a-f]*'),created_at INTEGER NOT NULL CHECK(created_at>=0),PRIMARY KEY(orchestration_id,revision))STRICT;CREATE TABLE orchestration_task_nodes(orchestration_id TEXT NOT NULL,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),task_node_id TEXT NOT NULL,task_key TEXT NOT NULL CHECK(length(task_key)BETWEEN 1 AND 128 AND trim(task_key)=task_key),description TEXT NOT NULL CHECK(length(description)BETWEEN 1 AND 8192),expected_output TEXT NOT NULL CHECK(expected_output IN('text','patch','design','test','plan','review','diagnostic','artifact')),required_model_capabilities_json TEXT NOT NULL CHECK(json_valid(required_model_capabilities_json)),allowed_model_profiles_json TEXT NOT NULL CHECK(json_valid(allowed_model_profiles_json)),data_class TEXT NOT NULL CHECK(data_class IN('public','workspace','sensitive')),required_compartments_json TEXT NOT NULL CHECK(json_valid(required_compartments_json)),required_tools_json TEXT NOT NULL CHECK(json_valid(required_tools_json)),max_input_tokens INTEGER NOT NULL CHECK(max_input_tokens>0),max_output_tokens INTEGER NOT NULL CHECK(max_output_tokens>0),max_attempts INTEGER NOT NULL CHECK(max_attempts>0),deadline_at INTEGER CHECK(deadline_at IS NULL OR deadline_at>=0),PRIMARY KEY(orchestration_id,graph_revision,task_node_id),UNIQUE(orchestration_id,graph_revision,task_key),FOREIGN KEY(orchestration_id,graph_revision)REFERENCES orchestration_graph_revisions(orchestration_id,revision)ON DELETE CASCADE)STRICT;CREATE TABLE orchestration_task_dependencies(orchestration_id TEXT NOT NULL,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),task_node_id TEXT NOT NULL,depends_on_task_node_id TEXT NOT NULL,PRIMARY KEY(orchestration_id,graph_revision,task_node_id,depends_on_task_node_id),CHECK(task_node_id<>depends_on_task_node_id),FOREIGN KEY(orchestration_id,graph_revision,task_node_id)REFERENCES orchestration_task_nodes(orchestration_id,graph_revision,task_node_id)ON DELETE CASCADE,FOREIGN KEY(orchestration_id,graph_revision,depends_on_task_node_id)REFERENCES orchestration_task_nodes(orchestration_id,graph_revision,task_node_id)ON DELETE RESTRICT)STRICT;CREATE TABLE orchestration_task_state_revisions(orchestration_id TEXT NOT NULL,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),task_node_id TEXT NOT NULL,state_revision INTEGER NOT NULL CHECK(state_revision>0),state TEXT NOT NULL CHECK(state IN('pending','ready','running','blocked','completed','failed','cancelled','unknown')),attempt_count INTEGER NOT NULL CHECK(attempt_count>=0),created_at INTEGER NOT NULL CHECK(created_at>=0),PRIMARY KEY(orchestration_id,graph_revision,task_node_id,state_revision),FOREIGN KEY(orchestration_id,graph_revision,task_node_id)REFERENCES orchestration_task_nodes(orchestration_id,graph_revision,task_node_id)ON DELETE CASCADE)STRICT;CREATE INDEX orchestration_graph_latest_idx ON orchestration_graph_revisions(orchestration_id,revision DESC);CREATE INDEX orchestration_task_key_idx ON orchestration_task_nodes(orchestration_id,graph_revision,task_key);CREATE INDEX orchestration_dependency_reverse_idx ON orchestration_task_dependencies(orchestration_id,graph_revision,depends_on_task_node_id,task_node_id);CREATE INDEX orchestration_task_state_latest_idx ON orchestration_task_state_revisions(orchestration_id,graph_revision,task_node_id,state_revision DESC);
